import {forms,chooseForm,reply} from './game.mjs';
import {createAudio} from './audio.js';
const $=id=>document.getElementById(id);let session=null,source=null,real=false,connecting=false,likes=0,gifts=0,ki=0,viewers=0,queue=[],busy=false,transformTimer,epoch=0,joinTimes=new Map(),lastChat=new Map(),rules={};
try{rules=JSON.parse(localStorage.getItem('goku-gift-rules')||'{}')}catch{}
let sessionPromise,aiReady=false,voiceReady=false,conversationQueue=[],conversationBusy=false,conversationController,conversationEpoch=0;
const audio=createAudio((speaking,text)=>{document.body.classList.toggle('speaking',speaking);if(speaking&&text)$('spoken').textContent=text},{speech:async(text,signal)=>{const res=await fetch('/api/ai/speech',{method:'POST',headers:{'Content-Type':'application/json','X-Session-Id':session},body:JSON.stringify({text}),signal});if(!res.ok){const data=await res.json();throw new Error(data.error||'Falha ao gerar a voz.')}return res.blob()}});
async function ensureSession(){if(session)return;if(!sessionPromise)sessionPromise=api('session').then(data=>{session=data.id}).finally(()=>{sessionPromise=null});await sessionPromise}
function intelligenceStatus(info){aiReady=info.chatConfigured&&info.unlocked;voiceReady=info.voiceConfigured&&info.unlocked;$('ai-enabled').disabled=!aiReady;$('ai-status').textContent=!info.chatConfigured?'IA ainda não configurada no servidor. Modo básico disponível.':!info.unlocked?'IA configurada. Digite o código do operador para ativar.':'IA ativa · contexto separado por usuário.';$('custom-voice-status').textContent=!info.voiceConfigured?'Voz personalizada ainda não configurada no servidor.':!info.unlocked?'Voz personalizada configurada. Desbloqueie para usar.':'Voz personalizada pronta para todas as falas.';audio.setCustomVoice(voiceReady)}
async function loadIntelligence(){try{await ensureSession();intelligenceStatus(await api('ai/status'))}catch{$('ai-status').textContent='Não foi possível verificar a IA. Atualize a página.'}}
async function conversationPump(){if(conversationBusy||!conversationQueue.length)return;conversationBusy=true;const event=conversationQueue.shift(),currentEpoch=conversationEpoch;conversationController=new AbortController();try{const res=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Session-Id':session},body:JSON.stringify({name:event.name,comment:event.comment}),signal:conversationController.signal});const data=await res.json();if(!res.ok)throw new Error(data.error||'Falha na resposta da IA.');if(currentEpoch===conversationEpoch){say(data.text);feed({name:'Goku',demo:event.demo},'Resposta a @'+event.name+': '+data.text);$('ai-status').textContent='IA ativa · '+conversationQueue.length+' comentário(s) aguardando.'}}catch(error){if(currentEpoch===conversationEpoch){$('ai-status').textContent=error.message;feed(event,'A IA não conseguiu responder a este comentário.')}}finally{if(currentEpoch===conversationEpoch){conversationBusy=false;conversationController=null;conversationPump()}}}
function respondComment(event){if(!aiReady||!$('ai-enabled').checked){say(reply(event));return}if(conversationQueue.length>=100){$('ai-status').textContent='Fila de comentários cheia. Aguarde a equipe terminar de conversar.';feed(event,'Comentário não respondido: fila de IA cheia.');return}conversationQueue.push(event);conversationPump()}
$('ai-unlock').onclick=async()=>{try{await ensureSession();intelligenceStatus(await api('ai/unlock',{token:$('operator-code').value}));$('operator-code').value=''}catch(error){$('operator-code').value='';$('ai-status').textContent=error.message}};
$('ai-reset').onclick=async()=>{cancelConversation();try{await api('ai/reset');$('ai-status').textContent='Históricos apagados. Cada usuário começa uma conversa nova.'}catch(error){$('ai-status').textContent=error.message}};
function cancelConversation(){conversationEpoch++;conversationQueue=[];conversationBusy=false;conversationController?.abort();conversationController=null;audio.clear()}

function form(index){const f=forms[index];$('stage').dataset.form=index;$('stage').style.setProperty('--aura',f.color);$('stage').classList.toggle('powered',index>0);document.querySelector('.sprite').style.backgroundPosition=(index*25)+'% center';$('form-name').textContent=f.name.toUpperCase();$('form-detail').textContent=index?'Essa energia veio da sua equipe.':'Envie energia. Desperte uma nova forma.'}
function counters(){$('likes').textContent=likes.toLocaleString('pt-BR');$('gifts').textContent=gifts.toLocaleString('pt-BR');$('viewers').textContent=viewers.toLocaleString('pt-BR');$('ki-value').textContent=Math.round(ki)+'%';$('ki-bar').style.width=ki+'%'}
function feed(e,text){const empty=$('feed').querySelector('.empty');empty?.remove();const li=document.createElement('li'),title=document.createElement('b'),sub=document.createElement('small');title.textContent=(e.demo?'[TESTE] ':'')+'@'+e.name;sub.textContent=text;li.append(title,sub);$('feed').prepend(li);while($('feed').children.length>35)$('feed').lastChild.remove()}
function say(text){$('spoken').textContent=text;audio.say(text)}
function animate(){const flash=$('flash');flash.classList.remove('burst');void flash.offsetWidth;flash.classList.add('burst');audio.burst()}
function pump(){if(busy||!queue.length)return;busy=true;const e=queue.shift(),index=chooseForm(e,rules),currentEpoch=epoch;gifts++;form(index);animate();counters();say(reply(e));feed(e,`${e.repeat||1} × ${e.giftName} → ${forms[index].name}`);transformTimer=setTimeout(()=>{if(currentEpoch!==epoch)return;busy=false;if(queue.length)pump();else form(0)},6500)}
function receive(e){if(['join','comment','gift','follow','share'].includes(e.type)&&!e.name)return;const now=Date.now();if(e.type==='gift'){if(queue.length>=100){feed(e,'Fila cheia: '+reply(e));audio.say(reply(e));return}queue.push(e);pump()}else if(e.type==='join'){if(now-(joinTimes.get(e.name)||0)<45000)return;joinTimes.set(e.name,now);say(reply(e));feed(e,'Entrou na live · boas-vindas!')}else if(e.type==='comment'){feed(e,e.comment);respondComment(e)}else if(e.type==='follow'){say(reply(e));feed(e,'Começou a seguir!')}else if(e.type==='share')feed(e,'Compartilhou a live!');else if(e.type==='like'){likes=e.total||likes+(e.count||0);const old=ki;ki=Math.min(100,ki+(e.count||0)/5);if(old<100&&ki===100){animate();say('A energia da equipe chegou ao máximo! Vocês são incríveis!')}}else if(e.type==='viewers')viewers=e.count||0;counters();for(const map of [joinTimes,lastChat])if(map.size>2000)map.delete(map.keys().next().value)}
function reset(){epoch++;cancelConversation();clearTimeout(transformTimer);queue=[];busy=false;likes=0;gifts=0;ki=0;viewers=0;joinTimes.clear();lastChat.clear();audio.clear();$('feed').replaceChildren();form(0);counters()}
function status(state,message){const was=real;connecting=state==='connecting';real=state==='connected';$('connection').textContent=message;$('badge').textContent=real?'● LIVE CONECTADA':connecting?'● CONECTANDO':'● DESCONECTADO';$('scene-status').textContent=real?'LIVE REAL':connecting?'CONECTANDO':'SEM CONEXÃO';$('mode').textContent=real?'Live real':connecting?'Conectando':'Desconectado';$('connect').disabled=real||connecting;$('disconnect').disabled=!(real||connecting);$('username').disabled=real||connecting;document.querySelectorAll('#demo button,#demo input').forEach(el=>el.disabled=real||connecting);if(real&&!was)reset();if(!real&&!connecting){reset();say('Pronto para voar. Conecte sua live ou teste as interações.')}}
async function api(path,body={}){const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(session?{'X-Session-Id':session}:{})},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw new Error(data.error||'Não foi possível conectar.');return data}
async function prepare(){if(session&&source)return;await ensureSession();source=new EventSource('/api/events?session='+encodeURIComponent(session));await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('O canal de eventos não respondeu. Atualize a página.')),12000);source.addEventListener('open',()=>{clearTimeout(timer);resolve()},{once:true});source.addEventListener('error',()=>{clearTimeout(timer);reject(new Error('Não foi possível abrir o canal de eventos.'))},{once:true})});source.addEventListener('status',e=>{const data=JSON.parse(e.data);status(data.status,data.message)});source.addEventListener('live',e=>{if(real)receive(JSON.parse(e.data))});source.addEventListener('notice',e=>$('connection').textContent=JSON.parse(e.data).message);source.onerror=()=>{if(real||connecting)status('error','Canal de eventos perdido. Tentando restabelecer…')};source.onopen=()=>{$('connection').textContent='Canal restabelecido. Verificando conexão com a live…'}}
$('connect').onclick=async()=>{status('connecting','Preparando conexão com a live…');try{await prepare();status('connecting','Buscando a live…');await api('connect',{username:$('username').value})}catch(e){if(source?.readyState===EventSource.CLOSED){source.close();source=null;session=null}status('error',e.message)}};
$('disconnect').onclick=async()=>{try{await api('disconnect');status('disconnected','Desconectado. Você já pode testar o jogo.')}catch(e){status('error',e.message)}};
function demo(e){if(real||connecting)return;e.demo=true;e.name=$('demo-name').value.trim()||'visitante_teste';receive(e)}
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo({type:b.dataset.demo,count:50}));document.querySelectorAll('[data-gift]').forEach(b=>b.onclick=()=>demo({type:'gift',giftName:b.dataset.gift,giftId:b.dataset.gift,cost:1,repeat:1}));$('chat-form').onsubmit=e=>{e.preventDefault();if(!$('comment').value.trim())return;demo({type:'comment',comment:$('comment').value});$('comment').value=''};
$('save-rule').onclick=()=>{const key=$('gift-key').value.trim();if(!key){$('rule-status').textContent='Informe o ID ou nome do presente.';return}rules[key]=Number($('gift-form').value);try{localStorage.setItem('goku-gift-rules',JSON.stringify(rules));$('rule-status').textContent=`${key} → ${forms[rules[key]].name}. Salvo neste navegador.`}catch{$('rule-status').textContent='Regra aplicada nesta sessão; o navegador bloqueou o armazenamento.'}};
$('reset-rules').onclick=()=>{rules={};try{localStorage.removeItem('goku-gift-rules')}catch{}$('rule-status').textContent='Regras padrão restauradas.'};
async function broadcast(){document.body.classList.add('broadcast');try{await document.documentElement.requestFullscreen()}catch{}}async function exit(){document.body.classList.remove('broadcast');try{if(document.fullscreenElement)await document.exitFullscreen()}catch{}}$('broadcast').onclick=broadcast;$('exit').onclick=exit;document.addEventListener('keydown',e=>{if(e.key==='Escape')exit()});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('broadcast')});if(new URLSearchParams(location.search).get('overlay')==='1')document.body.classList.add('broadcast');
for(let i=0;i<22;i++){const p=document.createElement('i');p.className='spark';p.style.left=(10+Math.random()*80)+'%';p.style.top=(65+Math.random()*35)+'%';p.style.animationDelay=(-Math.random()*4)+'s';p.style.animationDuration=(1.5+Math.random()*2)+'s';$('particles').append(p)}
form(0);counters();loadIntelligence();
